#include <stdlib.h>
#include <string.h>
#include <omp.h>

#if defined(__AVX512F__)
#define VW 16
#define MR 8
#define MC 128
#else
#define VW 8
#define MR 6
#define MC 120
#endif

#define NR (2 * VW)
#define KC 384
#define NC 256

typedef float vf __attribute__((vector_size(VW * 4)));
typedef float vfu __attribute__((vector_size(VW * 4), aligned(4)));

static float *bbuf = NULL;
static size_t bcap = 0;
static __thread float *abuf = NULL;

static void *alloc64(size_t bytes)
{
    bytes = (bytes + 63) & ~(size_t)63;
    if (bytes == 0) bytes = 64;
    return aligned_alloc(64, bytes);
}

static void pack_b_panel(const float *B, float *bp, int n, int jp)
{
    int j0 = jp * NR;
    int w = n - j0 < NR ? n - j0 : NR;
    float *dst = bp + (size_t)jp * n * NR;
    if (w == NR) {
        for (int k = 0; k < n; k++)
            memcpy(dst + (size_t)k * NR, B + (size_t)k * n + j0, NR * sizeof(float));
    } else {
        for (int k = 0; k < n; k++) {
            float *d = dst + (size_t)k * NR;
            const float *s = B + (size_t)k * n + j0;
            int j = 0;
            for (; j < w; j++) d[j] = s[j];
            for (; j < NR; j++) d[j] = 0.0f;
        }
    }
}

static void pack_a(const float *A, float *ap, int n, int i0, int mc, int kk, int kc)
{
    int nmp = (mc + MR - 1) / MR;
    for (int mp = 0; mp < nmp; mp++) {
        int r0 = i0 + mp * MR;
        int h = mc - mp * MR < MR ? mc - mp * MR : MR;
        float *dst = ap + (size_t)mp * kc * MR;
        for (int i = 0; i < h; i++) {
            const float *s = A + (size_t)(r0 + i) * n + kk;
            for (int k = 0; k < kc; k++) dst[k * MR + i] = s[k];
        }
        for (int i = h; i < MR; i++)
            for (int k = 0; k < kc; k++) dst[k * MR + i] = 0.0f;
    }
}

static void kernel(int kc, const float *restrict a, const float *restrict b,
                   float *restrict c, int ldc, int mr, int nr, int acc)
{
    vf c0[MR], c1[MR];
    vf z = {0};
#pragma GCC unroll 16
    for (int i = 0; i < MR; i++) { c0[i] = z; c1[i] = z; }

#pragma GCC unroll 4
    for (int k = 0; k < kc; k++) {
        vf b0 = *(const vf *)(b + (size_t)k * NR);
        vf b1 = *(const vf *)(b + (size_t)k * NR + VW);
        const float *ak = a + (size_t)k * MR;
#pragma GCC unroll 16
        for (int i = 0; i < MR; i++) {
            float av = ak[i];
            c0[i] += av * b0;
            c1[i] += av * b1;
        }
    }

    if (mr == MR && nr == NR) {
        if (acc) {
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++) {
                vfu *p = (vfu *)(c + (size_t)i * ldc);
                p[0] += c0[i];
                p[1] += c1[i];
            }
        } else {
#pragma GCC unroll 16
            for (int i = 0; i < MR; i++) {
                vfu *p = (vfu *)(c + (size_t)i * ldc);
                p[0] = c0[i];
                p[1] = c1[i];
            }
        }
    } else {
        float tmp[MR * NR] __attribute__((aligned(64)));
        for (int i = 0; i < MR; i++) {
            *(vf *)(tmp + i * NR) = c0[i];
            *(vf *)(tmp + i * NR + VW) = c1[i];
        }
        for (int i = 0; i < mr; i++) {
            float *ci = c + (size_t)i * ldc;
            if (acc)
                for (int j = 0; j < nr; j++) ci[j] += tmp[i * NR + j];
            else
                for (int j = 0; j < nr; j++) ci[j] = tmp[i * NR + j];
        }
    }
}

void matmul(const float *A, const float *B, float *C, int n)
{
    if (n <= 0) return;

    int npanels = (n + NR - 1) / NR;
    size_t bneed = (size_t)npanels * n * NR;
    if (bneed > bcap) {
        free(bbuf);
        bbuf = (float *)alloc64(bneed * sizeof(float));
        bcap = bneed;
    }
    float *bp = bbuf;

    int nmb = (n + MC - 1) / MC;
    int nnb = (n + NC - 1) / NC;
    int ntasks = nmb * nnb;

    #pragma omp parallel
    {
        if (!abuf) abuf = (float *)alloc64((size_t)MC * KC * sizeof(float));
        float *ap = abuf;

        #pragma omp for schedule(static)
        for (int jp = 0; jp < npanels; jp++)
            pack_b_panel(B, bp, n, jp);

        #pragma omp for schedule(dynamic, 1)
        for (int t = 0; t < ntasks; t++) {
            int ib = t / nnb, jb = t % nnb;
            int i0 = ib * MC, mc = n - i0 < MC ? n - i0 : MC;
            int j0 = jb * NC, nc = n - j0 < NC ? n - j0 : NC;
            int nmp = (mc + MR - 1) / MR;
            int np = (nc + NR - 1) / NR;
            int jp0 = j0 / NR;

            for (int kk = 0; kk < n; kk += KC) {
                int kc = n - kk < KC ? n - kk : KC;
                pack_a(A, ap, n, i0, mc, kk, kc);
                for (int mp = 0; mp < nmp; mp++) {
                    int mr = mc - mp * MR < MR ? mc - mp * MR : MR;
                    const float *am = ap + (size_t)mp * kc * MR;
                    float *crow = C + (size_t)(i0 + mp * MR) * n;
                    for (int p = 0; p < np; p++) {
                        int jc = j0 + p * NR;
                        int nr = nc - p * NR < NR ? nc - p * NR : NR;
                        const float *bm = bp + ((size_t)(jp0 + p) * n + kk) * NR;
                        kernel(kc, am, bm, crow + jc, n, mr, nr, kk > 0);
                    }
                }
            }
        }
    }
}
